INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63136974', 63136974, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PEKERJAAN UMUM DAN TATA RUANG', 'Perencanaan Teknis Jalan Program Partisipatif Kecamatan Pacet', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 100000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'a. Kegiatan Persiapan b. Kegiatan Survei Lapangan c. Pengujian Tanah d. Analisa Data Lapangan e. Perencanaan Detail f. Penggambaran g. Perhitungan Kuantitas h. Perkiraan Biaya', '1. SNI Perencanaan Jalan dan pembebanan Jalan 2. Pedoman Perencanaan Teknis Jalan (Bina Marga) 3. SNI Hidrologi dan Hidraulika 4. Manual Perencanaan Geometrik Jalan 5. Peraturan keselamatan lalu lintas dan bangunan pelengkap jalan 6. Ketentuan teknis lain yang relevan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 661180);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63137065', 63137065, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Pengembangan Modul Layanan Perizinan Teknis Perkeretaapian', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Meningkatkan kehandalan dan integrasi sistem layanan perizinan teknis perkeretaapian berbasis digital, mencakup aspek izin perpotongan dan persinggungan jalur rel kereta api dengan bangunan lain, penetapan lintas pelayanan, serta akreditasi kelembagaan, dengan pendekatan berbasis microservices, keamanan data tinggi, dan interoperabilitas dengan sistem eksternal. Sedangkan tujuan kegiatan ini adalah: 1. Memudahkan Badan Usaha dalam memperoleh izin perpotongan dan persinggungan jalur rel kereta api dengan bangunan lain, penetapan lintas pelayanan, serta akreditasi kelembagaan melalui sistem elektronik yang terintegrasi. 2. Mempercepat proses evaluasi dan persetujuan izin lintas pelayanan dengan berbasis data spasial dan teknis yang terdokumentasi. 3. Menyediakan dashboard monitoring izin perpotongan dan persinggungan jalur rel kereta api dengan bangunan lain. 4. Mendukung pengambilan keputusan strategis di tingkat pimpinan dengan penyajian data izin secara visual, informatif, dan terkini. 5. Mengoptimalkan pengawasan terhadap seluruh perizinan teknis bidang perkeretaapian melalui sistem digital yang terintegrasi dengan sistem pengawasan dan pelaporan.', 'Ruang lingkup kegiatan Pengembangan Modul Layanan Perizinan Teknis Bidang Perkeretaapian sebagai berikut: 1. Perubahan arsitektur sistem/modul layanan dengan menggunakan teknologi microservices atau arsitektur berorientasi layanan termasuk penyesuaian teknologi standar dengan Portal Layanan dan Data Direktorat Jenderal Perkeretaapian. 2. Optimalisasi penerapan integrasi Single Sign On (SSO), SPLT (Sistem Penghubung Layanan Transportasi) HUBNET Kementerian Perhubungan pada modul layanan perizinan teknis bidang perkeretaapian yang terintegrasi dengan Portal Layanan Direktorat Jenderal Perkeretaapian (superapps) mendukung persetujuan terpusat dan data warehouse termasuk integrasi sistem dengan SIMPONI dan eksternal Direktorat Jenderal Perkeretaapian. 3. Penyesuaian tampilan User Interface (UI) dan User Experience (UX) agar selaras dengan desain dan standar Portal Layanan Direktorat Jenderal Perkeretaapian. 4. Penyeragaman teknologi database sesuai dengan standar Portal Layanan Direktorat Jenderal Perkeretaapian, serta melakukan peningkatan performa database melalui penyederhanaan relasi dan optimasi struktur basis data. 5. Penambahan fitur layanan diantaranya : a. Penyesuaian/penyempurnaan proses bisnis perizinan perpotongan dan persinggungan jalur rel kereta api dengan bangunan lain sebagaimana peraturan/SOP yang berlaku; b. Penyesuaian/penyempurnaan proses bisnis penetapan lintas pelayanan perkeretaapian; c. Penyesuaian/penyempurnaan proses bisnis akreditasi kelembagaan perkeretaapian sebagaimana peraturan/SOP yang berlaku. 6. Penyediaan Web Services untuk integrasi data dengan HUBNET Kemenhub dan ESB Direktorat Jenderal Perkeretaapian. 7. Penerapan fitur Tanda Tangan Elektronik (TTE) yang sudah terintegrasi dengan portal TTE Kementerian Perhubungan dan BSrE untuk memenuhi kebutuhan layanan proses perizinan. 8. Pengembangan fitur pelaporan, monitoring, dashboard dan GIS (Geospatial Information System) untuk mempermudah pimpinan dalam monitoring hal-hal strategis dengan data, informasi dan laporan secara realtime/update. 9. Peningkatan user dan role management terkait penggunaan modul layanan perizinan bidang perkeretaapian termasuk integrasi dengan SIK Kementerian Perhubungan. 10. Peningkatan keamanan dan kinerja Modul Layanan Perizinan Bidang Perkeretaapian termasuk melakukan uji keamanan/pentest dan update modul layanan. 11. Workshop/pelatihan untuk pemroses perizinan/evaluator serta sosialisasi modul layanan perizinan dengan stakeholder.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 661181);
