INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62575492', 62575492, 'analyze_legacy', 'Kejaksaan Republik Indonesia', 'central', 'KEJAKSAAN NEGERI MUSI BANYUASIN', 'Belanja Pengadaan Outsourcing', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Selatan, Musi Banyu Asin (Kab.)', 2118600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'LINGKUP PEKERJAAN, TENAGA KERJA DAN LOKASI KERJA a. Lingkup Kegiatan Meliputi : 1. Ruang kerja, Ruang PTSP, Gudang, Klinik, R. Tahanan, KM/WC, R. Kontrol Mesin, Ruang Posko Pemilu. 2. R. Kajari, R. Rapat Besar, R. Rapat Intel, R. Rapat Pidum, R. Rapat Datun, R. Pembinaan, R. Aula, R. Pendopo, R. Staff, R. Tamu, Bidang Tindak Pidana Umum, Bidang Pembinaan, Bidang Intelijen, Bidang Tindak Pidana Khusus, Bidang Perdata dan Tata Usaha Negara, dan Aula. 3. Halaman Gedung kantor Kejaksaan Negeri Musi Banyuasin. Ruang lingkup yang dilakukan pekerjaannya dilakukan oleh petugas pramubakti/cleaning service per hari antara lain sebagai berikut : 1. Pembersihan area ruangan kerja meliputi : kebersihan lantai, jendela, langit-langit salasar, ruang kerja serta peralatan kantor yang menunjang kegiatan antara lain : meja, kursi, lemari, rak-rak (rak buku), kamar mandi, ruang rapat pimpinan, halaman gedung kantor yang ada dilingkungan Kejaksaan Negeri Musi Banyuasin. 2. Pembersih toilet/kamar mandi/WC pimpinan dan staff meliputi : Lantai, dinding, wastafel, cermin, kloset, saluran air kotor, jendela , pintu dan langit-langit di tiap ruangan 3. Kebersihan lobby, dinding, terali, tempat abu rokok dan kotak sampah, pintu dinding, ruang aula. 4. Pembersihan halaman Gedung kantor Kejaksaan Negeri Musi Banyuasin. Ruang Lingkup Pekerjaan Tenaga Satuan Pengamanan : 1. Pengamanan area kantor bagian luar maupun bagian dalam Gedung di area tertentu. 2. Pengaturan dan penertiban parkir kendaraan dalam lingkungan kantor. 3. Pengamanan di luar lokasi kantor jika diperlukan dan diminta baik di rumah dinas/jabatan pimpinan, pengamanan parkir di luar kantor. 4. Pengawasan terhadap tamu yang berkunjung dan memasuki area kantor. 5. Hal-hal lain yang berkaitan dengan tugas dan fungsi satuan pengamanan.', 'KLASIFIKASI BADAN USAHA DAN SUB KLASIFIKASI PEKERJAAN : Usaha Kecil, KBLI : 8120 KBLI Aktifitas Kebersihan Umum Bangunan (81210), KBLI Aktifitas Penyedia Gabungan Jasa Penunjang Fasilitas (81100) dan KBLI (80100) Penyedia Tenaga Outsourcing dan Keamanan Swasta, Sertifikat sebagai perusahaan cleaning service yang dikeluarkan oleh Asosiasi Perusahaan Klining Service Indonesia (APKLINDO) yang masih berlaku ; Sertifikat Asosiasi Badan Usaha Jasa Pengaman Indonesia (ABUJAPI) yang masih berlaku, Surat Domisili Perusahaan yang masih berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 663677);
