INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65763952', 65763952, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Sewa Rumah tidak bersusun', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Banjar (Kota)', 15000000, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Penyewaan rumah tinggal dari pihak ketiga untuk mendukung pelaksanaan tugas dan kebutuhan operasional instansi sesuai ketentuan yang berlaku. Pekerjaan meliputi penyediaan unit rumah dalam kondisi layak huni, aman, dan siap digunakan selama jangka waktu sewa yang disepakati dalam tahun anggaran berjalan, serta dilengkapi perjanjian sewa sebagai dasar pembayaran dan pertanggungjawaban.', 'Penyediaan unit rumah tinggal tapak dalam kondisi layak huni, aman, dan memiliki fasilitas dasar seperti jaringan listrik, air bersih, sanitasi, serta akses yang memadai, dengan status kepemilikan yang jelas dan tidak dalam sengketa. Rumah diserahkan dalam kondisi siap digunakan selama masa sewa yang disepakati, dilengkapi perjanjian sewa yang sah, serta ketentuan pemeliharaan dan tanggung jawab para pihak sesuai peraturan yang berlaku.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 665447);
