INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63119027', 63119027, 'analyze_legacy', 'Kab. Gresik', 'kabkota', 'RSUD IBNU SINA', 'BELANJA ALAT KEDOKTERAN UMUM (CYTOTOXIC SAFETY CABINET)', 'Barang', 'E-Purchasing', 'Jawa Timur, Gresik (Kab.)', 543678000, 'January 2026', 'BLUD', 1, 1, '1 UNIT', 'PEMBELIAN CYTOTOXIC DRUG CABINET UNTUK KEBUTUHAN PEMERIKSAAN ONKOLOGI', 'A. Persyaratan Umum • Barang merupakan peralatan medis baru (bukan rekondisi). • Digunakan untuk penyiapan dan pencampuran obat sitotoksik/kemoterapi. • Memberikan perlindungan petugas, produk, dan lingkungan. • Dapat digunakan di Instalasi Farmasi Rumah Sakit. • Dilengkapi izin edar Kemenkes RI yang masih berlaku. B. Klasifikasi • Termasuk Biological Safety Cabinet (BSC) Class II Type B2. • Sistem total exhaust (100% udara dibuang ke luar ruangan). • Tidak terjadi resirkulasi udara ke ruang kerja. C. Sistem Aliran Udara • Sistem aliran udara laminar vertikal. • Kecepatan aliran udara:  Inflow ± 0,5 m/detik  Downflow ± 0,3 m/detik • Tekanan kerja negatif untuk mencegah kebocoran aerosol berbahaya. D. Sistem Filtrasi • Menggunakan HEPA Filter minimal kelas H14. • Efisiensi filtrasi ≥ 99,995% pada partikel 0,3 mikron. • Terdiri dari:  HEPA filter supply  HEPA filter exhaust E. Standar Mutu • Memenuhi standar internasional yang relevan, antara lain:  EN 12469 atau setara  NSF/ANSI 49 atau setara  ISO 14644  USP <797> dan <800> • Dibuktikan dengan sertifikat atau dokumen pendukung resmi. F. Material & Konstruksi • Area kerja terbuat dari stainless steel minimal AISI 304. • Tahan terhadap bahan kimia dan mudah dibersihkan. • Kaca depan menggunakan tempered safety glass. • Desain ergonomis dan aman bagi pengguna. G. Sistem Kontrol & Keamanan • Dilengkapi panel kontrol digital. • Memiliki alarm visual dan audio apabila terjadi:  Gangguan aliran udara  Filter tersumbat  Posisi kaca depan tidak aman  Gangguan blower H. Pencahayaan • Lampu kerja LED dengan intensitas minimal 800 lux.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 668005);
