INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63119592', 63119592, 'analyze_legacy', 'Kab. Gresik', 'kabkota', 'RSUD IBNU SINA', 'BELANJA MODAL ALAT KEDOKTERAN RADIODIAGNOSTIC (COMPUTED RADIOGRAPHY (CR))', 'Barang', 'E-Purchasing', 'Jawa Timur, Gresik (Kab.)', 817515000, 'January 2026', 'BLUD', 1, 0, '1 UNIT', 'PEMBELIAN COMPUTED RADIOGRAPHY UNTUK INSTALASI RADIOLOGI DI GEDUNG PONEK', '1. Jenis Alat • Sistem radiografi digital berbasis Computed Radiography (CR) • Menggunakan Imaging Plate (IP) sebagai media penangkap citra sinar-X 2. Fungsi Utama • Mengakuisisi, memproses, dan menampilkan citra radiografi digital • Digunakan untuk pemeriksaan radiologi umum 3. Komponen Utama • Unit pembaca Imaging Plate (CR Reader) • Imaging Plate (IP) berbagai ukuran • Kaset CR • Workstation pengolahan citra • Perangkat lunak pengolahan dan penyimpanan gambar 4. Ukuran Imaging Plate • Mendukung berbagai ukuran standar, antara lain:  18 × 24 cm  24 × 30 cm  35 × 43 cm • Kompatibel dengan meja dan bucky standar radiologi 5. Kualitas Citra • Resolusi tinggi dengan kedalaman bit minimal 12 bit • Dynamic range luas untuk optimalisasi detail anatomi • Mendukung pengaturan kontras dan kecerahan secara digital 6. Sistem Pemrosesan • Proses pembacaan dan penghapusan data IP secara otomatis • Waktu pemrosesan cepat • Mendukung pengolahan citra lanjutan (image enhancement) 7. Konektivitas dan Integrasi • Mendukung standar DICOM 3.0 • Dapat terintegrasi dengan PACS dan HIS/RIS • Koneksi jaringan LAN 8. Antarmuka Pengguna • Tampilan grafis yang mudah dioperasikan • Mendukung pengaturan protokol pemeriksaan 9. Keamanan dan Keselamatan • Sistem proteksi terhadap kesalahan operasional • Mengurangi kebutuhan pengulangan pemeriksaan • Memenuhi standar keselamatan alat kesehatan 10. Catu Daya • Menggunakan listrik AC standar • Dilengkapi sistem proteksi kelistrikan 11. Standar dan Regulasi • Memiliki izin edar alat kesehatan • Memenuhi standar internasional dan nasional yang berlaku', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 669465);
